import React from 'react'
import { LayoutDashboard, Package, ClipboardList, Users, Boxes, Settings, LogOut, Plus, Pencil, Trash2, Upload, Save, X, RefreshCw, ChevronDown, ChevronUp, Eye, EyeOff, ShoppingCart, Banknote, UserRound, AlertTriangle, TicketPercent, Star, Search, Truck, Copy, Download, FileSpreadsheet, Palette, Database, Presentation, FileJson, UploadCloud, ShieldAlert, Menu as MenuIcon } from 'lucide-react'

const formatPrice=n=>new Intl.NumberFormat('uk-UA').format(Number(n)||0)+' ₴'
const STATUS={new:['Нове','status-new'],confirmed:['Підтверджено','status-confirmed'],shipped:['Відправлено','status-shipped'],done:['Виконано','status-done'],cancelled:['Скасовано','status-cancelled']}
const DELIVERY_STATUS={pending:'Очікує відправки',preparing:'Готується',handed_over:'Передано перевізнику',in_transit:'В дорозі',arrived:'Прибуло у відділення',received:'Отримано клієнтом',returned:'Повернення'}
const CARRIERS=['Нова пошта','Укрпошта','Meest Пошта','Самовивіз','Інше']
const emptyProduct={name:'',price:'',category:'',image:'',shortDescription:'',description:'',dimensions:'',material:'',colors:'',availability:'В наявності',availabilityMode:'auto',specs:'',gallery:'',active:true,sku:'',stock:0,isNew:false,bestseller:false,salePercent:0,oldPrice:0,slug:'',seoTitle:'',seoDescription:''}

async function api(path,options={},token=''){const headers={...(options.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(path,{...options,headers});const d=await r.json().catch(()=>({}));if(r.status===401&&token){sessionStorage.removeItem('nordhome-admin-token');window.dispatchEvent(new Event('nordhome-admin-auth-expired'))}if(!r.ok||d.ok===false)throw new Error(d.error||'Помилка сервера');return d}

function Login({onLogin}){const[username,setUsername]=React.useState('admin'),[password,setPassword]=React.useState(''),[show,setShow]=React.useState(false),[error,setError]=React.useState(''),[busy,setBusy]=React.useState(false);const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{const d=await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});sessionStorage.setItem('nordhome-admin-token',d.token);onLogin(d.token)}catch(err){setError(err.message)}finally{setBusy(false)}};return <main className="admin-login-wrap"><form className="admin-login" onSubmit={submit}><div className="admin-brand">NORDHOME</div><p>Панель керування магазином</p><label>Логін<input autoFocus value={username} onChange={e=>setUsername(e.target.value)} required/></label><label>Пароль<div className="password-field"><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} required/><button type="button" onClick={()=>setShow(v=>!v)}>{show?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>{error&&<div className="admin-error">{error}</div>}<button className="primary wide" disabled={busy}>{busy?'Входимо…':'Увійти'}</button></form></main>}

function Dashboard({token}){const[data,setData]=React.useState(null),[products,setProducts]=React.useState([]),[error,setError]=React.useState('');const load=React.useCallback(async()=>{try{const[d,p]=await Promise.all([api('/api/admin/dashboard',{},token),api('/api/admin/products',{},token)]);setData(d);setProducts(p.products||[]);setError('')}catch(e){setError(e.message)}},[token]);React.useEffect(()=>{load()},[load]);if(error)return <div className="admin-error">{error}</div>;if(!data)return <div className="admin-loading">Завантаження…</div>;const s=data.stats||{},low=products.filter(p=>p.availabilityMode==='auto'&&Number(p.stock)>0&&Number(p.stock)<=3).sort((a,b)=>a.stock-b.stock),out=products.filter(p=>p.availabilityMode==='out'||(p.availabilityMode==='auto'&&Number(p.stock)<=0)),missingPhoto=products.filter(p=>!String(p.image||'').trim()).length,missingSku=products.filter(p=>!String(p.sku||'').trim()).length,missingSeo=products.filter(p=>!String(p.seoTitle||'').trim()||!String(p.seoDescription||'').trim()).length,missingDescription=products.filter(p=>!String(p.description||'').trim()).length;return <section className="admin-section"><div className="admin-section-head"><div><h2>Dashboard</h2><p>Огляд NordHome на зараз</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Оновити</button></div><div className="admin-kpi-grid"><Kpi icon={<Banknote/>} title="Виручка" value={formatPrice(s.revenue)} sub={`Цього місяця: ${formatPrice(s.monthRevenue)}`}/><Kpi icon={<ShoppingCart/>} title="Замовлення" value={s.orders} sub={`Цього місяця: ${s.monthOrders}`}/><Kpi icon={<UserRound/>} title="Клієнти" value={s.customers} sub="Унікальні за телефоном"/><Kpi icon={<Package/>} title="Товари" value={s.products} sub={`Активних: ${s.activeProducts} · Акцій: ${s.saleProducts||0}`}/><Kpi icon={<Boxes/>} title="Одиниць на складі" value={s.stockUnits} sub="Сумарний залишок"/><Kpi icon={<AlertTriangle/>} title="Малий залишок" value={low.length} sub="1–3 одиниці на авто-режимі"/></div><div className="admin-dashboard-grid"><div className="admin-panel"><h3>Статуси замовлень</h3>{Object.entries(STATUS).map(([k,v])=><div className="status-row" key={k}><span className={`status-dot ${v[1]}`}></span><span>{v[0]}</span><strong>{s.statuses?.[k]||0}</strong></div>)}</div><div className="admin-panel"><h3>Останні замовлення</h3>{!data.recentOrders?.length?<p className="muted">Замовлень поки немає.</p>:data.recentOrders.map(o=><div className="recent-order" key={o.id}><div><strong>{o.id}</strong><span>{o.customer}</span></div><div><strong>{formatPrice(o.total)}</strong><span>{new Date(o.createdAt).toLocaleDateString('uk-UA')}</span></div></div>)}</div><div className="admin-panel catalog-health"><h3>Проблеми каталогу</h3><div className="catalog-health-grid"><div><b>{out.length}</b><span>Немає в наявності</span></div><div><b>{missingPhoto}</b><span>Без фото</span></div><div><b>{missingSku}</b><span>Без SKU</span></div><div><b>{missingSeo}</b><span>Без SEO</span></div><div><b>{missingDescription}</b><span>Без опису</span></div></div></div><div className="admin-panel"><h3>Закінчуються товари</h3>{!low.length?<p className="muted">Низьких залишків немає.</p>:low.slice(0,6).map(p=><div className="recent-order" key={p.id}><div><strong>{p.name}</strong><span>{p.sku||'без SKU'}</span></div><div><strong>{p.stock} шт.</strong><span>{p.category}</span></div></div>)}</div></div></section>}
function Kpi({icon,title,value,sub}){return <article className="admin-kpi"><div className="admin-kpi-icon">{icon}</div><div><span>{title}</span><strong>{value}</strong><small>{sub}</small></div></article>}


class AdminErrorBoundary extends React.Component{
  constructor(props){super(props);this.state={error:null}}
  static getDerivedStateFromError(error){return {error}}
  componentDidCatch(error,info){console.error('Admin section crashed:',error,info)}
  componentDidUpdate(prevProps){if(prevProps.resetKey!==this.props.resetKey&&this.state.error)this.setState({error:null})}
  render(){if(this.state.error)return <section className="admin-section"><div className="admin-error"><strong>Не вдалося відкрити цей розділ.</strong><br/>Оновіть сторінку або перейдіть в інший розділ адмінки.</div></section>;return this.props.children}
}

function Customers({token}){
  const[customers,setCustomers]=React.useState([]),[loading,setLoading]=React.useState(true),[error,setError]=React.useState(''),[search,setSearch]=React.useState('')
  const load=React.useCallback(async()=>{setLoading(true);try{const d=await api('/api/admin/customers',{},token);setCustomers(Array.isArray(d.customers)?d.customers:[]);setError('')}catch(e){setError(e.message||'Не вдалося завантажити клієнтів.')}finally{setLoading(false)}},[token])
  React.useEffect(()=>{load()},[load])
  const q=search.trim().toLowerCase()
  const filtered=customers.filter(c=>!q||[c.firstName,c.lastName,c.phone,c.email].some(v=>String(v||'').toLowerCase().includes(q)))
  const date=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('uk-UA')}
  return <section className="admin-section">
    <div className="admin-section-head"><div><h2>Клієнти</h2><p>Клієнтська база за оформленими замовленнями</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Оновити</button></div>
    <div className="admin-toolbar"><div className="admin-search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Пошук за ім’ям, телефоном або email"/></div></div>
    {error&&<div className="admin-error">{error}</div>}
    {loading?<div className="admin-loading">Завантаження…</div>:!filtered.length?<div className="admin-panel"><p className="muted">{customers.length?'За вашим пошуком клієнтів не знайдено.':'Клієнтів поки немає.'}</p></div>:<div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Клієнт</th><th>Телефон</th><th>Email</th><th>Замовлень</th><th>Сума</th><th>Останнє замовлення</th></tr></thead><tbody>{filtered.map((c,i)=><tr key={`${c.phone||c.email||'customer'}-${i}`}><td><strong>{`${c.firstName||''} ${c.lastName||''}`.trim()||'Без імені'}</strong></td><td>{c.phone||'—'}</td><td>{c.email||'—'}</td><td>{Number(c.ordersCount)||0}</td><td><strong>{formatPrice(c.spent)}</strong></td><td>{date(c.lastOrder)}</td></tr>)}</tbody></table></div>}
  </section>
}

function Orders({token}){
  const[orders,setOrders]=React.useState([]),[loading,setLoading]=React.useState(true),[error,setError]=React.useState(''),[open,setOpen]=React.useState(null)
  const[search,setSearch]=React.useState(''),[statusFilter,setStatusFilter]=React.useState('all'),[carrierFilter,setCarrierFilter]=React.useState('all'),[deliveryFilter,setDeliveryFilter]=React.useState('all')
  const load=React.useCallback(async()=>{setLoading(true);try{setOrders((await api('/api/admin/orders',{},token)).orders||[]);setError('')}catch(e){setError(e.message)}finally{setLoading(false)}},[token])
  React.useEffect(()=>{load()},[load])
  const status=async(id,value)=>{try{const d=await api(`/api/admin/orders/${encodeURIComponent(id)}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:value})},token);setOrders(v=>v.map(o=>o.id===id?d.order:o))}catch(e){setError(e.message)}}
  const saveShipment=async(order)=>{try{const d=await api(`/api/admin/orders/${encodeURIComponent(order.id)}/shipment`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({trackingNumber:order.trackingNumber||'',shipmentCarrier:order.shipmentCarrier||order.delivery?.carrier||'',deliveryStatus:order.deliveryStatus||'pending'})},token);setOrders(v=>v.map(o=>o.id===order.id?d.order:o));setError('')}catch(e){setError(e.message)}}
  const patchLocal=(id,field,value)=>setOrders(v=>v.map(o=>o.id===id?{...o,[field]:value}:o))
  const q=search.trim().toLowerCase()
  const filtered=orders.filter(o=>{
    const hay=[o.id,o.customer?.firstName,o.customer?.lastName,o.customer?.phone,o.customer?.email,o.trackingNumber,o.shipmentCarrier,o.delivery?.carrier,o.delivery?.city].filter(Boolean).join(' ').toLowerCase()
    return(!q||hay.includes(q))&&(statusFilter==='all'||o.status===statusFilter)&&(carrierFilter==='all'||(o.shipmentCarrier||o.delivery?.carrier||'')===carrierFilter)&&(deliveryFilter==='all'||(o.deliveryStatus||'pending')===deliveryFilter)
  })
  const carriers=[...new Set([...CARRIERS,...orders.map(o=>o.shipmentCarrier||o.delivery?.carrier).filter(Boolean)])]
  return <section className="admin-section"><div className="admin-section-head"><div><h2>Замовлення</h2><p>{filtered.length} з {orders.length} замовлень</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Оновити</button></div>
    <div className="order-admin-filters"><label className="order-search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Пошук: номер, клієнт, телефон, email, ТТН…"/></label><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">Усі статуси замовлення</option>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v[0]}</option>)}</select><select value={carrierFilter} onChange={e=>setCarrierFilter(e.target.value)}><option value="all">Усі служби доставки</option>{carriers.map(x=><option key={x} value={x}>{x}</option>)}</select><select value={deliveryFilter} onChange={e=>setDeliveryFilter(e.target.value)}><option value="all">Усі статуси доставки</option>{Object.entries(DELIVERY_STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div>
    {error&&<div className="admin-error">{error}</div>}{loading?<div className="admin-loading">Завантаження…</div>:!filtered.length?<div className="admin-empty">За цими фільтрами замовлень немає.</div>:<div className="order-admin-list">{filtered.map(order=>{const isOpen=open===order.id,st=STATUS[order.status]||STATUS.new;return <article className="order-admin-card" key={order.id}><div className="order-admin-summary"><div><strong>{order.id}</strong><span>{new Date(order.createdAt).toLocaleString('uk-UA')}</span>{order.trackingNumber&&<small className="tracking-chip">ТТН {order.trackingNumber}</small>}</div><div><strong>{order.customer?.firstName} {order.customer?.lastName}</strong><span>{order.customer?.phone}</span></div><div><strong>{formatPrice(order.total)}</strong><span>{order.shipmentCarrier||order.delivery?.carrier||'—'}</span><small>{DELIVERY_STATUS[order.deliveryStatus||'pending']}</small></div><select className={`status-select ${st[1]}`} value={order.status||'new'} onChange={e=>status(order.id,e.target.value)}>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v[0]}</option>)}</select><button className="admin-icon" onClick={()=>setOpen(isOpen?null:order.id)}>{isOpen?<ChevronUp/>:<ChevronDown/>}</button></div>
      {isOpen&&<div className="order-admin-detail"><div><h4>Клієнт</h4><p>{order.customer?.firstName} {order.customer?.lastName}</p><p>{order.customer?.phone}</p><p>{order.customer?.email||'—'}</p></div><div><h4>Адреса доставки</h4><p>{order.delivery?.carrier} — {order.delivery?.deliveryType}</p><p>{order.delivery?.city}</p><p>{order.delivery?.point||order.delivery?.address||'—'}</p></div><div><h4>Оплата</h4><p>{order.payment}</p>{order.comment&&<p>{order.comment}</p>}</div>
      <div className="shipment-editor"><div className="shipment-editor-title"><Truck size={18}/><div><h4>Відправлення / ТТН</h4><small>Ці дані бачить клієнт у кабінеті та відстеженні.</small></div></div><div className="shipment-grid"><label>Служба доставки<select value={order.shipmentCarrier||order.delivery?.carrier||''} onChange={e=>patchLocal(order.id,'shipmentCarrier',e.target.value)}><option value="">—</option>{carriers.map(x=><option key={x} value={x}>{x}</option>)}</select></label><label>Номер ТТН<div className="shipment-ttn-input"><input value={order.trackingNumber||''} onChange={e=>patchLocal(order.id,'trackingNumber',e.target.value)} placeholder="Наприклад 2045…"/>{order.trackingNumber&&<button type="button" title="Скопіювати ТТН" onClick={()=>navigator.clipboard?.writeText(order.trackingNumber)}><Copy size={15}/></button>}</div></label><label>Статус доставки<select value={order.deliveryStatus||'pending'} onChange={e=>patchLocal(order.id,'deliveryStatus',e.target.value)}>{Object.entries(DELIVERY_STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><button type="button" className="primary shipment-save" onClick={()=>saveShipment(order)}><Save size={16}/>Зберегти доставку</button></div>{order.shipmentUpdatedAt&&<small className="shipment-updated">Оновлено: {new Date(order.shipmentUpdatedAt).toLocaleString('uk-UA')}</small>}</div>
      <div className="order-items-admin"><h4>Товари</h4>{order.items?.map((i,idx)=><div key={idx}><span>{i.name} × {i.quantity}</span><strong>{formatPrice(i.price*i.quantity)}</strong></div>)}</div></div>}</article>})}</div>}</section>
}
function ProductEditor({product,token,onClose,onSaved}){const[form,setForm]=React.useState(()=>product?{...product,colors:(product.colors||[]).join(', '),specs:(product.specs||[]).join('\n'),gallery:(product.gallery||[]).join('\n')}:{...emptyProduct}),[busy,setBusy]=React.useState(false),[uploading,setUploading]=React.useState(false),[error,setError]=React.useState('');const field=name=>({value:form[name]??'',onChange:e=>setForm(v=>({...v,[name]:e.target.value}))});const upload=async e=>{const file=e.target.files?.[0];if(!file)return;setUploading(true);try{if(file.size>8_000_000)throw new Error('Максимальний розмір фото — 8 МБ.');const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const d=await api('/api/admin/upload-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl})},token);setForm(v=>({...v,image:d.url,gallery:v.gallery?`${v.gallery}\n${d.url}`:d.url}))}catch(err){setError(err.message)}finally{setUploading(false);e.target.value=''}};const save=async e=>{e.preventDefault();setBusy(true);try{const payload={...form,price:Number(form.price),stock:Number(form.stock),salePercent:Number(form.salePercent),oldPrice:Number(form.oldPrice),isNew:Boolean(form.isNew),bestseller:Boolean(form.bestseller),colors:form.colors.split(',').map(v=>v.trim()).filter(Boolean),specs:form.specs.split('\n').map(v=>v.trim()).filter(Boolean),gallery:form.gallery.split('\n').map(v=>v.trim()).filter(Boolean),active:Boolean(form.active)};const d=await api(product?`/api/admin/products/${product.id}`:'/api/admin/products',{method:product?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},token);onSaved(d.product)}catch(err){setError(err.message)}finally{setBusy(false)}};return <div className="admin-modal-backdrop"><form className="admin-modal" onSubmit={save}><div className="admin-modal-head"><div><h2>{product?'Редагувати товар':'Новий товар'}</h2><p>Зміни одразу потраплять у PostgreSQL.</p></div><button type="button" className="admin-icon" onClick={onClose}><X/></button></div><div className="product-edit-grid"><label>Назва<input required {...field('name')}/></label><label>Категорія<input required {...field('category')}/></label><label>Ціна, грн<input required type="number" min="0" {...field('price')}/></label><label>SKU / артикул<input {...field('sku')}/></label><label>Залишок<input type="number" min="0" {...field('stock')}/></label><label>Статус наявності<select value={form.availabilityMode||'auto'} onChange={e=>setForm(v=>({...v,availabilityMode:e.target.value,availability:e.target.value==='preorder'?(v.availability?.includes('Під замовлення')?v.availability:'Під замовлення'):e.target.value==='out'?'Немає в наявності':'В наявності'}))}><option value="auto">Автоматично по залишку</option><option value="preorder">Під замовлення</option><option value="out">Немає в наявності</option></select></label>{form.availabilityMode==='preorder'&&<label className="full">Текст під замовлення<input placeholder="Напр. Під замовлення 7–14 днів" {...field('availability')}/></label>}<div className="admin-merch-box full"><div className="admin-merch-title"><strong>Просування товару</strong><span>Ці позначки одразу з’являються у каталозі.</span></div><div className="admin-merch-grid"><label className="checkbox-label"><input type="checkbox" checked={Boolean(form.isNew)} onChange={e=>setForm(v=>({...v,isNew:e.target.checked}))}/><span>Новинка</span></label><label className="checkbox-label"><input type="checkbox" checked={Boolean(form.bestseller)} onChange={e=>setForm(v=>({...v,bestseller:e.target.checked}))}/><span>Хіт продажу</span></label><label>Знижка, %<input type="number" min="0" max="95" {...field('salePercent')}/></label><label>Стара ціна, грн<input type="number" min="0" {...field('oldPrice')}/></label></div><small>Поточна ціна — поле «Ціна, грн». Якщо є знижка, стара ціна має бути більшою за поточну.</small></div><label className="full">Короткий опис<input {...field('shortDescription')}/></label><label className="full">Повний опис<textarea {...field('description')}/></label><label>Розміри<input {...field('dimensions')}/></label><label>Матеріал<input {...field('material')}/></label><label className="full">Кольори через кому<input {...field('colors')}/></label><label className="full">Характеристики — кожна з нового рядка<textarea {...field('specs')}/></label><label className="full">Головне фото<input required {...field('image')}/></label><label className="upload-box full"><Upload size={22}/><span>{uploading?'Завантажуємо…':'Завантажити фото'}</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={upload}/></label>{form.image&&<div className="admin-image-preview full"><img src={form.image} alt=""/></div>}<label className="full">Галерея — одне посилання в рядку<textarea {...field('gallery')}/></label><div className="full admin-template-settings"><h3>SEO товару</h3><p>Красивий URL і тексти для результатів пошуку та соцмереж.</p></div><label>URL slug<input placeholder="dyvan-oslo" {...field('slug')}/></label><label className="full">SEO title<input maxLength="180" placeholder="Напр. Диван Осло — NordHome" {...field('seoTitle')}/></label><label className="full">SEO description<textarea maxLength="320" placeholder="Короткий опис товару для Google" {...field('seoDescription')}/></label><label className="checkbox-label full"><input type="checkbox" checked={Boolean(form.active)} onChange={e=>setForm(v=>({...v,active:e.target.checked}))}/><span>Показувати у каталозі</span></label></div>{error&&<div className="admin-error">{error}</div>}<div className="admin-modal-actions"><button type="button" className="secondary" onClick={onClose}>Скасувати</button><button className="primary" disabled={busy||uploading}><Save size={17}/>{busy?'Зберігаємо…':'Зберегти товар'}</button></div></form></div>}

const PRODUCT_COLUMNS=['name','sku','category','price','oldPrice','stock','image','shortDescription','description','dimensions','material','colors','availabilityMode','availability','specs','gallery','isNew','bestseller','salePercent','active','slug','seoTitle','seoDescription']
const PRODUCT_LABELS={name:'Назва',sku:'SKU',category:'Категорія',price:'Ціна',oldPrice:'Стара ціна',stock:'Залишок',image:'Головне фото URL',shortDescription:'Короткий опис',description:'Опис',dimensions:'Розміри',material:'Матеріал',colors:'Кольори',availabilityMode:'Режим наявності',availability:'Текст наявності',specs:'Характеристики',gallery:'Галерея URL',isNew:'Новинка',bestseller:'Хіт',salePercent:'Знижка %',active:'Активний',slug:'Slug',seoTitle:'SEO title',seoDescription:'SEO description'}
const csvCell=v=>`"${String(v??'').replaceAll('"','""')}"`
function productFlat(p){return {...p,colors:(p.colors||[]).join('|'),specs:(p.specs||[]).join('|'),gallery:(p.gallery||[]).join('|'),isNew:p.isNew?'1':'0',bestseller:p.bestseller?'1':'0',active:p.active===false?'0':'1'}}
function downloadBlob(name,type,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function csvText(rows){return [PRODUCT_COLUMNS.map(k=>csvCell(PRODUCT_LABELS[k])).join(';'),...rows.map(p=>{const f=productFlat(p);return PRODUCT_COLUMNS.map(k=>csvCell(f[k])).join(';')})].join('\r\n')}
function excelXml(rows){const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');const data=[PRODUCT_COLUMNS.map(k=>PRODUCT_LABELS[k]),...rows.map(p=>{const f=productFlat(p);return PRODUCT_COLUMNS.map(k=>f[k]??'')})];return `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Products"><Table>${data.map(r=>`<Row>${r.map(v=>`<Cell><Data ss:Type="String">${esc(v)}</Data></Cell>`).join('')}</Row>`).join('')}</Table></Worksheet></Workbook>`}
function parseCsv(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){cell+='"';i++}else q=!q}else if(!q&&(c===';'||c===',')){row.push(cell);cell=''}else if(!q&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);cell='';if(row.some(x=>x.trim()))rows.push(row);row=[]}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function rowsToProducts(rows){if(rows.length<2)return[];const norm=v=>String(v||'').trim().toLowerCase();const aliases={};PRODUCT_COLUMNS.forEach(k=>{aliases[norm(k)]=k;aliases[norm(PRODUCT_LABELS[k])]=k});const headers=rows[0].map(h=>aliases[norm(h)]||'');return rows.slice(1).filter(r=>r.some(v=>String(v).trim())).map(r=>{const o={};headers.forEach((k,i)=>{if(k)o[k]=r[i]??''});['price','oldPrice','stock','salePercent'].forEach(k=>o[k]=Number(String(o[k]||'0').replace(',','.'))||0);['isNew','bestseller','active'].forEach(k=>o[k]=!['0','false','ні','no'].includes(norm(o[k])));['colors','specs','gallery'].forEach(k=>o[k]=String(o[k]||'').split('|').map(v=>v.trim()).filter(Boolean));return o})}
function parseExcelXml(text){const doc=new DOMParser().parseFromString(text,'application/xml');const rows=[...doc.getElementsByTagNameNS('*','Row')].map(r=>[...r.getElementsByTagNameNS('*','Data')].map(d=>d.textContent||''));return rowsToProducts(rows)}

function Products({token,onProductsChanged}){const[products,setProducts]=React.useState([]),[loading,setLoading]=React.useState(true),[error,setError]=React.useState(''),[editing,setEditing]=React.useState(undefined),[importing,setImporting]=React.useState(false),[report,setReport]=React.useState(null),[search,setSearch]=React.useState(''),[stockFilter,setStockFilter]=React.useState('all'),[category,setCategory]=React.useState('all'),[visibility,setVisibility]=React.useState('all'),[quality,setQuality]=React.useState('all'),[sort,setSort]=React.useState('name');const load=React.useCallback(async()=>{setLoading(true);try{setProducts((await api('/api/admin/products',{},token)).products||[]);setError('')}catch(e){setError(e.message)}finally{setLoading(false)}},[token]);React.useEffect(()=>{load()},[load]);const saved=p=>{setProducts(v=>v.some(x=>x.id===p.id)?v.map(x=>x.id===p.id?p:x):[...v,p]);setEditing(undefined);onProductsChanged?.()};const remove=async p=>{if(!window.confirm(`Видалити ${p.name}?`))return;try{await api(`/api/admin/products/${p.id}`,{method:'DELETE'},token);setProducts(v=>v.filter(x=>x.id!==p.id));onProductsChanged?.()}catch(e){setError(e.message)}};const exportCsv=()=>downloadBlob('nordhome-products.csv','text/csv;charset=utf-8',csvText(products));const exportExcel=()=>downloadBlob('nordhome-products.xls','application/vnd.ms-excel',excelXml(products));const templateCsv=()=>downloadBlob('nordhome-import-template.csv','text/csv;charset=utf-8',csvText([{name:'Приклад товару',sku:'SKU-001',category:'Дивани',price:24900,oldPrice:0,stock:5,image:'https://example.com/photo.jpg',shortDescription:'Короткий опис',description:'Повний опис',dimensions:'220×95×85 см',material:'Тканина',colors:['Бежевий','Сірий'],availabilityMode:'auto',availability:'В наявності',specs:['Каркас: дерево','Гарантія: 12 міс.'],gallery:['https://example.com/photo.jpg'],isNew:false,bestseller:false,salePercent:0,active:true,slug:'pryklad-tovaru',seoTitle:'',seoDescription:''}]));const importFile=async e=>{const file=e.target.files?.[0];if(!file)return;setImporting(true);setError('');setReport(null);try{const text=await file.text();let parsed;if(file.name.toLowerCase().endsWith('.xls')||text.includes('<Workbook'))parsed=parseExcelXml(text);else parsed=rowsToProducts(parseCsv(text));if(!parsed.length)throw new Error('Не знайдено рядків товарів. Використайте наш шаблон CSV або Excel XML (.xls).');const d=await api('/api/admin/products/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({products:parsed})},token);setReport(d);await load();onProductsChanged?.()}catch(err){setError(err.message)}finally{setImporting(false);e.target.value=''}};const cats=[...new Set(products.map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'));const isOut=p=>p.availabilityMode==='out'||(p.availabilityMode==='auto'&&Number(p.stock)<=0),isLow=p=>p.availabilityMode==='auto'&&Number(p.stock)>0&&Number(p.stock)<=3,isIn=p=>p.availabilityMode==='auto'&&Number(p.stock)>3;const filtered=products.filter(p=>{const q=search.trim().toLowerCase();if(q&&!`${p.name} ${p.sku||''} ${p.category||''}`.toLowerCase().includes(q))return false;if(category!=='all'&&p.category!==category)return false;if(visibility==='active'&&p.active===false)return false;if(visibility==='hidden'&&p.active!==false)return false;if(stockFilter==='in'&&!isIn(p))return false;if(stockFilter==='low'&&!isLow(p))return false;if(stockFilter==='out'&&!isOut(p))return false;if(stockFilter==='preorder'&&p.availabilityMode!=='preorder')return false;if(quality==='photo'&&String(p.image||'').trim())return false;if(quality==='sku'&&String(p.sku||'').trim())return false;if(quality==='seo'&&String(p.seoTitle||'').trim()&&String(p.seoDescription||'').trim())return false;if(quality==='description'&&String(p.description||'').trim())return false;return true}).sort((a,b)=>sort==='stockAsc'?Number(a.stock)-Number(b.stock):sort==='stockDesc'?Number(b.stock)-Number(a.stock):sort==='priceAsc'?Number(a.price)-Number(b.price):sort==='priceDesc'?Number(b.price)-Number(a.price):String(a.name).localeCompare(String(b.name),'uk'));const issues={out:products.filter(isOut).length,low:products.filter(isLow).length,photo:products.filter(p=>!String(p.image||'').trim()).length,sku:products.filter(p=>!String(p.sku||'').trim()).length,seo:products.filter(p=>!String(p.seoTitle||'').trim()||!String(p.seoDescription||'').trim()).length};return <section className="admin-section"><div className="admin-section-head"><div><h2>Товари</h2><p>{products.length} позицій · показано {filtered.length}</p></div><div className="admin-catalog-actions"><button className="secondary" onClick={templateCsv}><Download size={16}/>Шаблон CSV</button><button className="secondary" onClick={exportCsv}><Download size={16}/>Експорт CSV</button><button className="secondary" onClick={exportExcel}><FileSpreadsheet size={16}/>Експорт Excel</button><label className="primary admin-import-button"><Upload size={17}/>{importing?'Імпортуємо…':'Імпорт CSV / Excel'}<input type="file" accept=".csv,.xls,text/csv,application/vnd.ms-excel" onChange={importFile} disabled={importing}/></label><button className="primary" onClick={()=>setEditing(null)}><Plus size={17}/>Додати товар</button></div></div><div className="catalog-health-strip"><button onClick={()=>setStockFilter('low')}><b>{issues.low}</b><span>Малий залишок</span></button><button onClick={()=>setStockFilter('out')}><b>{issues.out}</b><span>Немає</span></button><button onClick={()=>setQuality('photo')}><b>{issues.photo}</b><span>Без фото</span></button><button onClick={()=>setQuality('sku')}><b>{issues.sku}</b><span>Без SKU</span></button><button onClick={()=>setQuality('seo')}><b>{issues.seo}</b><span>Без SEO</span></button></div><div className="product-admin-filters"><div className="order-search"><Search size={16}/><input placeholder="Пошук назва / SKU / категорія" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={stockFilter} onChange={e=>setStockFilter(e.target.value)}><option value="all">Всі залишки</option><option value="in">В наявності</option><option value="low">Мало (1–3)</option><option value="out">Немає</option><option value="preorder">Передзамовлення</option></select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="all">Всі категорії</option>{cats.map(c=><option key={c}>{c}</option>)}</select><select value={visibility} onChange={e=>setVisibility(e.target.value)}><option value="all">Активні + приховані</option><option value="active">Тільки активні</option><option value="hidden">Тільки приховані</option></select><select value={quality} onChange={e=>setQuality(e.target.value)}><option value="all">Якість: усі</option><option value="photo">Без фото</option><option value="sku">Без SKU</option><option value="seo">Без SEO</option><option value="description">Без опису</option></select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="name">За назвою</option><option value="stockAsc">Залишок ↑</option><option value="stockDesc">Залишок ↓</option><option value="priceAsc">Ціна ↑</option><option value="priceDesc">Ціна ↓</option></select></div><div className="admin-import-note"><strong>Імпорт:</strong> SKU вже існує — товар оновиться; нового SKU — створиться. До 1000 товарів за один раз.</div>{report&&<div className="admin-import-report">Готово: створено <b>{report.created}</b>, оновлено <b>{report.updated}</b>, пропущено <b>{report.skipped}</b>.{report.errors?.length>0&&<details><summary>Показати помилки ({report.errors.length})</summary>{report.errors.map((x,i)=><div key={i}>{x}</div>)}</details>}</div>}{error&&<div className="admin-error">{error}</div>}{loading?<div className="admin-loading">Завантаження…</div>:!filtered.length?<div className="admin-empty-filter">Нічого не знайдено за вибраними фільтрами.</div>:<div className="admin-products-grid">{filtered.map(p=><article className={`admin-product-card ${p.active===false?'inactive':''}`} key={p.id}><div className="admin-product-image-wrap">{p.image?<img src={p.image} alt={p.name}/>:<div className="missing-product-image">Без фото</div>}<span className={`stock-badge ${isOut(p)?'out':isLow(p)?'low':p.availabilityMode==='preorder'?'preorder':'ok'}`}>{p.availabilityMode==='preorder'?'Передзамовлення':isOut(p)?'Немає':isLow(p)?`${p.stock} шт. · мало`:`${p.stock} шт.`}</span></div><div><span>{p.category} · {p.sku||'без SKU'}</span><div className="admin-card-merch">{p.active===false&&<b>Приховано</b>}{p.salePercent>0&&<b>−{p.salePercent}%</b>}{p.isNew&&<b>Новинка</b>}{p.bestseller&&<b>Хіт</b>}</div><h3>{p.name}</h3><div className="admin-price-pair"><strong>{formatPrice(p.price)}</strong>{p.oldPrice>p.price&&<del>{formatPrice(p.oldPrice)}</del>}</div><p>{p.availabilityMode==='preorder'?'Під замовлення':isOut(p)?'Немає в наявності':isLow(p)?`Закінчується · ${p.stock} шт.`:`В наявності · ${p.stock} шт.`}</p></div><div className="admin-product-actions"><button className="secondary" onClick={()=>setEditing(p)}><Pencil size={15}/>Редагувати</button><button className="danger" onClick={()=>remove(p)}><Trash2 size={15}/>Видалити</button></div></article>)}</div>}{editing!==undefined&&<ProductEditor product={editing} token={token} onClose={()=>setEditing(undefined)} onSaved={saved}/>}</section>}

function Inventory({token}){const[items,setItems]=React.useState([]),[error,setError]=React.useState(''),[search,setSearch]=React.useState(''),[status,setStatus]=React.useState('all'),[mode,setMode]=React.useState('all'),[category,setCategory]=React.useState('all'),[sort,setSort]=React.useState('stockAsc'),[selected,setSelected]=React.useState([]),[bulkBusy,setBulkBusy]=React.useState(false);const load=React.useCallback(()=>api('/api/admin/products',{},token).then(d=>{setItems(d.products||[]);setError('')}).catch(e=>setError(e.message)),[token]);React.useEffect(()=>{load()},[load]);const setStock=async(p,stock)=>{stock=Math.max(0,Number(stock)||0);setItems(v=>v.map(x=>x.id===p.id?{...x,stock}:x));try{const d=await api(`/api/admin/products/${p.id}/stock`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({stock})},token);setItems(v=>v.map(x=>x.id===p.id?d.product:x))}catch(e){setError(e.message);load()}};const setAvailability=async(p,availabilityMode)=>{try{const d=await api(`/api/admin/products/${p.id}/availability`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({availabilityMode,availability:p.availability})},token);setItems(v=>v.map(x=>x.id===p.id?d.product:x))}catch(e){setError(e.message)}};const label=p=>p.availabilityMode==='preorder'?'Під замовлення':p.availabilityMode==='out'?'Немає в наявності':p.stock>0?`В наявності${p.stock<=3?' · мало':''}`:'Немає в наявності';const cats=[...new Set(items.map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'uk'));const matchesStatus=p=>status==='all'||(status==='in'&&p.availabilityMode==='auto'&&p.stock>3)||(status==='low'&&p.availabilityMode==='auto'&&p.stock>0&&p.stock<=3)||(status==='out'&&(p.availabilityMode==='out'||(p.availabilityMode==='auto'&&p.stock<=0)))||(status==='preorder'&&p.availabilityMode==='preorder');const filtered=items.filter(p=>{const q=search.trim().toLowerCase();return(!q||`${p.name} ${p.sku||''} ${p.category||''}`.toLowerCase().includes(q))&&matchesStatus(p)&&(mode==='all'||p.availabilityMode===mode)&&(category==='all'||p.category===category)}).sort((a,b)=>sort==='stockDesc'?b.stock-a.stock:sort==='name'?a.name.localeCompare(b.name,'uk'):sort==='category'?String(a.category).localeCompare(String(b.category),'uk'):a.stock-b.stock);const toggle=id=>setSelected(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);const allVisible=filtered.length>0&&filtered.every(p=>selected.includes(p.id));const toggleAll=()=>setSelected(v=>allVisible?v.filter(id=>!filtered.some(p=>p.id===id)):[...new Set([...v,...filtered.map(p=>p.id)])]);const bulkAvailability=async value=>{if(!selected.length)return;setBulkBusy(true);setError('');try{for(const p of items.filter(x=>selected.includes(x.id)))await setAvailability(p,value);setSelected([])}finally{setBulkBusy(false)}};const bulkActive=async active=>{if(!selected.length)return;setBulkBusy(true);setError('');try{for(const p of items.filter(x=>selected.includes(x.id))){const d=await api(`/api/admin/products/${p.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...p,active})},token);setItems(v=>v.map(x=>x.id===p.id?d.product:x))}setSelected([])}catch(e){setError(e.message)}finally{setBulkBusy(false)}};return <section className="admin-section"><div className="admin-section-head"><div><h2>Залишки</h2><p>{items.length} товарів · показано {filtered.length}</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Оновити</button></div><div className="inventory-summary"><button onClick={()=>setStatus('in')}><b>{items.filter(p=>p.availabilityMode==='auto'&&p.stock>3).length}</b><span>В наявності</span></button><button onClick={()=>setStatus('low')}><b>{items.filter(p=>p.availabilityMode==='auto'&&p.stock>0&&p.stock<=3).length}</b><span>Мало</span></button><button onClick={()=>setStatus('out')}><b>{items.filter(p=>p.availabilityMode==='out'||(p.availabilityMode==='auto'&&p.stock<=0)).length}</b><span>Немає</span></button><button onClick={()=>setStatus('preorder')}><b>{items.filter(p=>p.availabilityMode==='preorder').length}</b><span>Передзамовлення</span></button></div><div className="inventory-filters"><div className="order-search"><Search size={16}/><input placeholder="Пошук назва / SKU / категорія" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Всі статуси</option><option value="in">В наявності</option><option value="low">Мало (1–3)</option><option value="out">Немає</option><option value="preorder">Передзамовлення</option></select><select value={mode} onChange={e=>setMode(e.target.value)}><option value="all">Всі режими</option><option value="auto">Авто</option><option value="preorder">Під замовлення</option><option value="out">Немає</option></select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="all">Всі категорії</option>{cats.map(c=><option key={c}>{c}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="stockAsc">Залишок ↑</option><option value="stockDesc">Залишок ↓</option><option value="name">За назвою</option><option value="category">За категорією</option></select></div>{selected.length>0&&<div className="inventory-bulk"><strong>Вибрано: {selected.length}</strong><button disabled={bulkBusy} onClick={()=>bulkAvailability('auto')}>Авто</button><button disabled={bulkBusy} onClick={()=>bulkAvailability('preorder')}>Під замовлення</button><button disabled={bulkBusy} onClick={()=>bulkAvailability('out')}>Немає</button><button disabled={bulkBusy} onClick={()=>bulkActive(true)}>Активувати</button><button disabled={bulkBusy} onClick={()=>bulkActive(false)}>Приховати</button><button onClick={()=>setSelected([])}>Скасувати</button></div>}{error&&<div className="admin-error">{error}</div>}<div className="admin-table-wrap"><table className="admin-table inventory-table"><thead><tr><th><input type="checkbox" checked={allVisible} onChange={toggleAll}/></th><th>Товар</th><th>SKU</th><th>Категорія</th><th>Залишок</th><th>Режим</th><th>Статус</th></tr></thead><tbody>{filtered.map(p=><tr key={p.id} className={selected.includes(p.id)?'selected-row':''}><td><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>toggle(p.id)}/></td><td><strong>{p.name}</strong>{p.active===false&&<small className="hidden-label">приховано</small>}</td><td>{p.sku||'—'}</td><td>{p.category}</td><td><div className="stock-stepper"><button onClick={()=>setStock(p,p.stock-1)}>−</button><input type="number" min="0" value={p.stock} onChange={e=>setItems(v=>v.map(x=>x.id===p.id?{...x,stock:Math.max(0,Number(e.target.value)||0)}:x))} onBlur={e=>setStock(p,e.target.value)}/><button onClick={()=>setStock(p,p.stock+1)}>+</button></div></td><td><select className="stock-mode-select" value={p.availabilityMode||'auto'} onChange={e=>setAvailability(p,e.target.value)}><option value="auto">Авто по залишку</option><option value="preorder">Під замовлення</option><option value="out">Немає</option></select></td><td><span className={`stock-status-pill ${p.availabilityMode==='preorder'?'preorder':p.availabilityMode==='out'||(p.availabilityMode==='auto'&&p.stock<=0)?'out':p.stock<=3?'low':'ok'}`}>{label(p)}</span></td></tr>)}</tbody></table>{!filtered.length&&<div className="admin-empty-filter">Немає товарів за вибраними фільтрами.</div>}</div><p className="inventory-hint">Швидке редагування: − / + змінюють залишок одразу. В полі можна ввести число й клікнути поза ним. Масові дії застосовуються до відмічених товарів.</p></section>}

function PromoCodes({token}){const[items,setItems]=React.useState([]),[editing,setEditing]=React.useState(null),[showForm,setShowForm]=React.useState(false),[error,setError]=React.useState('');const empty={code:'',discountType:'percent',discountValue:10,minOrder:0,maxUses:0,active:true,startsAt:'',endsAt:''};const load=React.useCallback(()=>api('/api/admin/promo-codes',{},token).then(d=>setItems(d.promoCodes||[])).catch(e=>setError(e.message)),[token]);React.useEffect(()=>{load()},[load]);const open=p=>{setEditing(p?{...p,startsAt:p.startsAt?.slice(0,16)||'',endsAt:p.endsAt?.slice(0,16)||''}:empty);setShowForm(true)};const save=async e=>{e.preventDefault();try{const isNew=!editing.id,d=await api(isNew?'/api/admin/promo-codes':`/api/admin/promo-codes/${editing.id}`,{method:isNew?'POST':'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(editing)},token);setItems(v=>isNew?[d.promoCode,...v]:v.map(x=>x.id===d.promoCode.id?d.promoCode:x));setShowForm(false);setEditing(null);setError('')}catch(err){setError(err.message)}};const remove=async p=>{if(!confirm(`Видалити промокод ${p.code}?`))return;try{await api(`/api/admin/promo-codes/${p.id}`,{method:'DELETE'},token);setItems(v=>v.filter(x=>x.id!==p.id))}catch(e){setError(e.message)}};const f=n=>({value:editing?.[n]??'',onChange:e=>setEditing(v=>({...v,[n]:e.target.value}))});return <section className="admin-section"><div className="admin-section-head"><div><h2>Промокоди</h2><p>Знижки для клієнтів у кошику</p></div><button className="primary" onClick={()=>open(null)}><Plus size={17}/>Створити промокод</button></div>{error&&<div className="admin-error">{error}</div>}<div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Код</th><th>Знижка</th><th>Мін. сума</th><th>Використано</th><th>Статус</th><th></th></tr></thead><tbody>{items.map(p=><tr key={p.id}><td><strong className="promo-code-chip">{p.code}</strong></td><td>{p.discountType==='percent'?`${p.discountValue}%`:formatPrice(p.discountValue)}</td><td>{p.minOrder?formatPrice(p.minOrder):'—'}</td><td>{p.used}{p.maxUses?` / ${p.maxUses}`:''}</td><td><span className={p.active?'stock-ok':'stock-low'}>{p.active?'Активний':'Вимкнений'}</span></td><td><div className="table-actions"><button className="secondary" onClick={()=>open(p)}><Pencil size={14}/></button><button className="danger" onClick={()=>remove(p)}><Trash2 size={14}/></button></div></td></tr>)}</tbody></table></div>{showForm&&editing&&<div className="admin-modal-backdrop"><form className="admin-modal promo-modal" onSubmit={save}><div className="admin-modal-head"><div><h3>{editing.id?'Редагувати промокод':'Новий промокод'}</h3><p>Код перевіряється сервером при оформленні.</p></div><button type="button" onClick={()=>setShowForm(false)}><X/></button></div><div className="product-edit-grid"><label>Код<input required maxLength="40" {...f('code')} onChange={e=>setEditing(v=>({...v,code:e.target.value.toUpperCase().replace(/[^A-Z0-9_-]/g,'')}))}/></label><label>Тип<select {...f('discountType')}><option value="percent">Відсоток %</option><option value="fixed">Фіксована сума ₴</option></select></label><label>Розмір знижки<input required type="number" min="1" max={editing.discountType==='percent'?95:9999999} {...f('discountValue')}/></label><label>Мінімальна сума замовлення<input type="number" min="0" {...f('minOrder')}/></label><label>Ліміт використань<input type="number" min="0" {...f('maxUses')}/><small>0 = без обмежень</small></label><label>Початок дії<input type="datetime-local" {...f('startsAt')}/></label><label>Кінець дії<input type="datetime-local" {...f('endsAt')}/></label><label className="checkbox-label"><input type="checkbox" checked={Boolean(editing.active)} onChange={e=>setEditing(v=>({...v,active:e.target.checked}))}/><span>Промокод активний</span></label></div><div className="admin-modal-actions"><button type="button" className="secondary" onClick={()=>setShowForm(false)}>Скасувати</button><button className="primary"><Save size={16}/>Зберегти</button></div></form></div>}</section>}


function Reviews({token}){
  const[items,setItems]=React.useState([]),[loading,setLoading]=React.useState(true),[error,setError]=React.useState(''),[search,setSearch]=React.useState(''),[status,setStatus]=React.useState('all')
  const load=React.useCallback(async()=>{setLoading(true);try{const d=await api('/api/admin/reviews',{},token);setItems(Array.isArray(d.reviews)?d.reviews:[]);setError('')}catch(e){setError(e.message||'Не вдалося завантажити відгуки.')}finally{setLoading(false)}},[token])
  React.useEffect(()=>{load()},[load])
  const changeStatus=async(id,nextStatus)=>{try{await api(`/api/admin/reviews/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:nextStatus})},token);setItems(v=>v.map(x=>x.id===id?{...x,status:nextStatus}:x));setError('')}catch(e){setError(e.message)}}
  const remove=async item=>{if(!window.confirm(`Видалити відгук від ${item.customerName||'клієнта'}?`))return;try{await api(`/api/admin/reviews/${item.id}`,{method:'DELETE'},token);setItems(v=>v.filter(x=>x.id!==item.id));setError('')}catch(e){setError(e.message)}}
  const q=search.trim().toLowerCase()
  const filtered=items.filter(r=>(status==='all'||r.status===status)&&(!q||`${r.customerName||''} ${r.productName||''} ${r.text||''}`.toLowerCase().includes(q)))
  const counts={all:items.length,pending:items.filter(x=>x.status==='pending').length,approved:items.filter(x=>x.status==='approved').length,hidden:items.filter(x=>x.status==='hidden').length}
  const statusLabel=s=>s==='approved'?'Опубліковано':s==='hidden'?'Приховано':'На модерації'
  return <section className="admin-section">
    <div className="admin-section-head"><div><h2>Відгуки</h2><p>Модерація відгуків та рейтингу товарів</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Оновити</button></div>
    <div className="inventory-summary reviews-summary"><button onClick={()=>setStatus('all')}><b>{counts.all}</b><span>Усі</span></button><button onClick={()=>setStatus('pending')}><b>{counts.pending}</b><span>На модерації</span></button><button onClick={()=>setStatus('approved')}><b>{counts.approved}</b><span>Опубліковано</span></button><button onClick={()=>setStatus('hidden')}><b>{counts.hidden}</b><span>Приховано</span></button></div>
    <div className="inventory-filters reviews-filters"><div className="order-search"><Search size={16}/><input placeholder="Пошук клієнт / товар / текст" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Усі статуси</option><option value="pending">На модерації</option><option value="approved">Опубліковано</option><option value="hidden">Приховано</option></select></div>
    {error&&<div className="admin-error">{error}</div>}
    {loading?<div className="admin-loading">Завантаження…</div>:!filtered.length?<div className="admin-panel"><p className="muted">{items.length?'За вибраними фільтрами відгуків немає.':'Відгуків поки немає.'}</p></div>:<div className="admin-table-wrap"><table className="admin-table reviews-table"><thead><tr><th>Клієнт</th><th>Товар</th><th>Оцінка</th><th>Відгук</th><th>Дата</th><th>Статус</th><th></th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td><strong>{r.customerName||'Без імені'}</strong></td><td>{r.productName||`Товар #${r.productId}`}</td><td><span className="review-stars" aria-label={`${r.rating} з 5`}>{'★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||0)))}{'☆'.repeat(Math.max(0,5-(Number(r.rating)||0)))}</span></td><td className="review-text-cell">{r.text||'—'}</td><td>{r.createdAt?new Date(r.createdAt).toLocaleDateString('uk-UA'):'—'}</td><td><span className={`review-status ${r.status||'pending'}`}>{statusLabel(r.status)}</span></td><td><div className="table-actions review-actions">{r.status!=='approved'&&<button className="secondary" title="Опублікувати" onClick={()=>changeStatus(r.id,'approved')}><Eye size={14}/></button>}{r.status!=='hidden'&&<button className="secondary" title="Приховати" onClick={()=>changeStatus(r.id,'hidden')}><EyeOff size={14}/></button>}{r.status!=='pending'&&<button className="secondary" title="Повернути на модерацію" onClick={()=>changeStatus(r.id,'pending')}><RefreshCw size={14}/></button>}<button className="danger" title="Видалити" onClick={()=>remove(r)}><Trash2 size={14}/></button></div></td></tr>)}</tbody></table></div>}
  </section>
}

function AdminTabContent({tab,token,navigate,onProductsChanged,onSettingsChanged}){
  if(tab==='dashboard')return <Dashboard token={token}/>
  if(tab==='orders')return <Orders token={token}/>
  if(tab==='products')return <Products token={token} onProductsChanged={onProductsChanged}/>
  if(tab==='customers')return <Customers token={token}/>
  if(tab==='inventory')return <Inventory token={token}/>
  if(tab==='promos')return <PromoCodes token={token}/>
  if(tab==='reviews')return <Reviews token={token}/>
  return <StoreSettings token={token} navigate={navigate} onSettingsChanged={onSettingsChanged}/>
}

function StoreSettings({token,onSettingsChanged,navigate}){
  const[form,setForm]=React.useState(null),[saved,setSaved]=React.useState(false),[error,setError]=React.useState(''),[notice,setNotice]=React.useState(''),[busy,setBusy]=React.useState(false),[transferStatus,setTransferStatus]=React.useState(null)
  const importInputRef=React.useRef(null)
  const load=React.useCallback(()=>api('/api/admin/settings',{},token).then(d=>setForm(d.settings||{})).catch(e=>setError(e.message)),[token])
  React.useEffect(()=>{load()},[load])
  if(!form)return <div className="admin-loading">Завантаження…</div>
  const f=n=>({value:form[n]??'',onChange:e=>setForm(v=>({...v,[n]:e.target.value}))})
  const save=async e=>{e.preventDefault();setBusy(true);try{const d=await api('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)},token);setForm(d.settings);onSettingsChanged?.();setSaved(true);setError('');setTimeout(()=>setSaved(false),2000)}catch(err){setError(err.message)}finally{setBusy(false)}}
  const exportSettings=async()=>{setTransferStatus({type:'loading',text:'Готуємо файл налаштувань…'});try{const d=await api('/api/admin/settings/export',{},token);const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${(form.storeName||'store').replace(/[^a-zа-яіїє0-9_-]+/gi,'-').toLowerCase()}-settings.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);setTransferStatus({type:'success',text:'Налаштування експортовано у JSON.'});setError('')}catch(e){setTransferStatus({type:'error',text:e.message||'Не вдалося експортувати налаштування.'})}}
  const importSettings=async e=>{const file=e.target.files?.[0];if(!file)return;setTransferStatus({type:'loading',text:`Перевіряємо ${file.name}…`});try{if(file.size>500_000)throw new Error('Файл завеликий. Максимум 500 КБ.');const text=await file.text();let parsed;try{parsed=JSON.parse(text)}catch{throw new Error('Це невалідний JSON-файл.')}const source=parsed?.settings&&typeof parsed.settings==='object'&&!Array.isArray(parsed.settings)?parsed.settings:parsed;if(!source||typeof source!=='object'||Array.isArray(source))throw new Error('У файлі немає коректних налаштувань магазину.');const d=await api('/api/admin/settings/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(parsed)},token);if(!d?.settings)throw new Error('Сервер не повернув імпортовані налаштування.');const verified=await api('/api/admin/settings',{},token);setForm(verified.settings||d.settings);setError('');setNotice('');setTransferStatus({type:'success',text:'Налаштування успішно імпортовано і збережено. Сторінку оновлено.'});onSettingsChanged?.()}catch(err){setTransferStatus({type:'error',text:err.message||'Не вдалося імпортувати налаштування.'})}finally{e.target.value=''}}
  const seedDemo=async()=>{if(!confirm('Додати демонстраційних клієнтів і замовлення для презентації сайту?'))return;setBusy(true);try{const d=await api('/api/admin/demo/seed',{method:'POST'},token);setForm(d.settings||form);onSettingsChanged?.();setNotice(`Демо готове: замовлень ${d.createdOrders}, клієнтів ${d.createdCustomers}.`)}catch(e){setError(e.message)}finally{setBusy(false)}}
  const clearDemo=async()=>{const code=prompt('УВАГА: буде видалено ВСІ замовлення та клієнтів. Для підтвердження введіть CLEAR_DEMO_DATA');if(code!=='CLEAR_DEMO_DATA')return;setBusy(true);try{const d=await api('/api/admin/demo/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:code})},token);setForm(d.cleared?.settings||form);onSettingsChanged?.();setNotice(`Очищено: замовлень ${d.cleared?.orders||0}, клієнтів ${d.cleared?.customers||0}.`)}catch(e){setError(e.message)}finally{setBusy(false)}}
  return <section className="admin-section"><div className="admin-section-head"><div><h2>Налаштування</h2><p>White Label, бренд, демо-режим і дані магазину</p></div><button className="secondary" type="button" onClick={()=>navigate('/template')}><Presentation size={17}/>Презентація шаблону</button></div>
    <form className="admin-settings-card" onSubmit={save}>
      <div className="full admin-template-settings"><h3>White Label — бренд за кілька хвилин</h3><p>Змініть назву, логотип, контакти й кольори — без редагування коду.</p></div>
      <label>Назва магазину<input {...f('storeName')}/></label><label>Телефон<input {...f('phone')}/></label><label>Email<input {...f('email')}/></label><label>Місто<input {...f('city')}/></label><label>Instagram<input {...f('instagram')}/></label><label>Поріг малого залишку<input type="number" min="0" {...f('lowStockThreshold')}/></label>
      <label className="full">URL логотипу<input placeholder="https://.../logo.png" {...f('logoUrl')}/></label>
      <div className="full admin-color-grid"><label>Основний колір<input type="color" value={form.primaryColor||'#1d1f1c'} onChange={e=>setForm(v=>({...v,primaryColor:e.target.value}))}/><span>{form.primaryColor||'#1d1f1c'}</span></label><label>Акцент<input type="color" value={form.accentColor||'#2f7d55'} onChange={e=>setForm(v=>({...v,accentColor:e.target.value}))}/><span>{form.accentColor||'#2f7d55'}</span></label><label>Фон<input type="color" value={form.surfaceColor||'#f8f7f3'} onChange={e=>setForm(v=>({...v,surfaceColor:e.target.value}))}/><span>{form.surfaceColor||'#f8f7f3'}</span></label></div>
      <label>Короткий слоган<input {...f('heroEyebrow')}/></label><label>Текст у футері<input {...f('footerText')}/></label><label className="full">Заголовок головного банера<input {...f('heroTitle')}/></label><label className="full">Опис головного банера<textarea {...f('heroText')}/></label><label className="full">Текст сторінки «Про магазин»<textarea {...f('aboutText')}/></label>
      <div className="full admin-template-settings"><h3>Презентація /template</h3><p>Ціни пакетів на сторінці продажу шаблону.</p></div><label>Пакет START<input {...f('templateStarterPrice')} placeholder="від 12 000 ₴"/></label><label>Пакет BUSINESS<input {...f('templateBusinessPrice')} placeholder="від 20 000 ₴"/></label><label>Пакет PRO<input {...f('templateProPrice')} placeholder="від 30 000 ₴"/></label>
      <div className="full admin-template-settings"><h3>Demo Mode</h3><p>Підготуйте магазин для показу покупцю, а перед передачею очистіть замовлення та клієнтів одним захищеним кроком.</p></div>
      <label className="checkbox-label"><input type="checkbox" checked={Boolean(form.demoMode)} onChange={e=>setForm(v=>({...v,demoMode:e.target.checked}))}/><span>Показувати позначку демо-режиму</span></label><label>Текст позначки<input {...f('demoBadge')} placeholder="Демо-магазин"/></label>
      <div className="full demo-tools"><button className="secondary" type="button" disabled={busy} onClick={seedDemo}><Database size={16}/>Створити демо-замовлення</button><button className="danger" type="button" disabled={busy} onClick={clearDemo}><ShieldAlert size={16}/>Очистити замовлення і клієнтів</button></div>
      <div className="full admin-template-settings"><h3>Перенесення налаштувань</h3><p>Експортуйте бренд у JSON і імпортуйте його в іншу копію NordHome.</p></div>
      <div className="full demo-tools"><button className="secondary" type="button" onClick={exportSettings}><Download size={16}/>Експорт налаштувань</button><button className="secondary" type="button" onClick={()=>importInputRef.current?.click()}><UploadCloud size={16}/>Імпорт налаштувань</button><input ref={importInputRef} className="settings-import-input" type="file" accept="application/json,.json" onChange={importSettings}/></div>{transferStatus&&<div className={`full transfer-status ${transferStatus.type}`} role="status" aria-live="polite">{transferStatus.text}</div>}
      <div className="full admin-template-settings"><h3>SEO магазину</h3><p>Головна сторінка, sitemap.xml і canonical.</p></div><label className="full">Публічна адреса сайту<input placeholder="https://example.com" {...f('publicUrl')}/></label><label className="full">SEO title головної<input maxLength="180" {...f('seoHomeTitle')}/></label><label className="full">SEO description головної<textarea maxLength="320" {...f('seoHomeDescription')}/></label>
      <div className="full admin-template-settings"><h3>Аналітика</h3><p>Google Analytics 4 і Meta Pixel.</p></div><label>Google Analytics 4 ID<input placeholder="G-XXXXXXXXXX" {...f('googleAnalyticsId')}/></label><label>Meta Pixel ID<input placeholder="123456789012345" {...f('metaPixelId')}/></label>
      <div className="full admin-template-settings"><h3>Юридичні сторінки</h3><p>Перед реальним запуском тексти варто перевірити під конкретний бізнес.</p></div><label className="full">Доставка та оплата<textarea rows="8" {...f('deliveryText')}/></label><label className="full">Повернення та обмін<textarea rows="8" {...f('returnsText')}/></label><label className="full">Публічна оферта<textarea rows="12" {...f('offerText')}/></label><label className="full">Політика конфіденційності<textarea rows="12" {...f('privacyText')}/></label>
      {error&&<div className="admin-error full">{error}</div>}{notice&&<div className="admin-success full">{notice}</div>}<div className="full settings-actions"><button className="primary" disabled={busy}><Save size={17}/>{saved?'Збережено ✓':busy?'Зачекайте…':'Зберегти'}</button></div>
    </form></section>
}

export default function AdminPage({navigate,onProductsChanged,onSettingsChanged}){const[token,setToken]=React.useState(()=>sessionStorage.getItem('nordhome-admin-token')||''),[tab,setTab]=React.useState('dashboard');React.useEffect(()=>{const expired=()=>setToken('');window.addEventListener('nordhome-admin-auth-expired',expired);return()=>window.removeEventListener('nordhome-admin-auth-expired',expired)},[]);if(!token)return <Login onLogin={setToken}/>;const logout=async()=>{try{await api('/api/admin/logout',{method:'POST'},token)}catch{}sessionStorage.removeItem('nordhome-admin-token');setToken('')};const tabs=[['dashboard','Огляд',LayoutDashboard],['orders','Замовлення',ClipboardList],['products','Товари',Package],['customers','Клієнти',Users],['inventory','Залишки',Boxes],['promos','Промокоди',TicketPercent],['reviews','Відгуки',Star],['settings','Налаштування',Settings]];return <main className="admin-shell"><aside className="admin-sidebar"><div className="admin-mobile-head"><button className="admin-logo" onClick={()=>navigate('/')}>NORDHOME</button></div><p>Адмін-панель</p><nav>{tabs.map(([id,label,Icon])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><Icon size={18}/>{label}</button>)}</nav><div className="admin-side-bottom"><button onClick={()=>navigate('/')}><span>←</span>До магазину</button><button onClick={logout}><LogOut size={17}/>Вийти</button></div></aside><div className="admin-content"><AdminErrorBoundary resetKey={tab}><AdminTabContent tab={tab} token={token} navigate={navigate} onProductsChanged={onProductsChanged} onSettingsChanged={onSettingsChanged}/></AdminErrorBoundary></div></main>}
